"""Module for reading the credits in YouTube descriptions.

Descriptions of songs that labels deliver to YouTube end with
"Auto-generated by YouTube." Before that line, they list one contributor
per line, as the roles of the contributor and then their name, e.g.:

    Associated  Performer, Drums: Roger Taylor
    Composer  Lyricist: Freddie Mercury

YouTube writes these lines from the release's metadata. The roles are
either names from the DDEX standard, like "Associated Performer", or
anything the label wrote itself, like "Drums". So there's no complete
list of roles, but the lines always have the same form.
"""
from typing import Final

from retag_opus import constants

Tags = dict[str, list[str]]

# Roles that say what kind of contributor someone is, and that come
# before their actual roles, e.g. "Associated Performer, Drums"
PERFORMER_CATEGORIES: Final[set[str]] = {"associated performer", "performer"}
OTHER_CATEGORIES: Final[set[str]] = {"studio personnel"}

# Roles and the tags their contributors are put in. Tags are named as in
# the Vorbis comment specification, or else as in Quod Libet, or else as
# in MusicBrainz Picard. Performer roles that are already the name of a
# common performer tag, e.g. "piano", aren't listed. An empty list means
# that no tag is used for the role, on purpose, even after "Associated
# Performer".
ROLE_TAGS: Final[dict[str, list[str]]] = {
    "artist": ["artist"],
    "composer": ["composer"],
    "composed by": ["composer"],
    "lyricist": ["lyricist"],
    "composer lyricist": ["composer", "lyricist"],
    "writer": ["writer"],
    "written by": ["writer"],
    "author": ["author"],
    "arranger": ["arranger"],
    "arranged by": ["arranger"],
    "string arranger": ["arranger"],
    "recording arranger": ["arranger"],
    "conductor": ["conductor"],
    "producer": ["producer"],
    "additional producer": ["producer"],
    # Picard leaves out recording and mastering engineers
    "mixer": ["mixer"],
    "mixing engineer": ["mixer"],
    "engineer": ["engineer"],
    "publisher": ["publisher"],
    "music publisher": ["publisher"],
    "vocals": ["performer:lead vocals"],
    "vocal": ["performer:lead vocals"],
    "lead vocal": ["performer:lead vocals"],
    "backing vocals": ["performer:background vocals"],
    "background vocal": ["performer:background vocals"],
    "background vocalist": ["performer:background vocals"],
    "drums": ["performer:drums (drum set)"],
    "drum": ["performer:drums (drum set)"],
    "keyboards": ["performer:keyboard"],
    "lead guitar": ["performer:guitar"],
    "rhythm guitar": ["performer:guitar"],
    "electric bass": ["performer:electric bass guitar"],
    "synth": ["performer:synthesizer"],
    # Programming isn't an instrument, and neither Quod Libet nor Picard
    # has a tag for it
    "programming": [],
    "programmer": [],
    "drum programming": [],
    "drum programmer": [],
    # Roles that say nothing about what the contributor did
    "unknown": [],
    "other": [],
}


def normalize_role(role: str) -> str:
    """Make a role comparable, e.g. "Associated  Performer" → "associated performer".

    YouTube sometimes puts two spaces between the words of a role.
    """
    return " ".join(role.split()).lower()


def role_tag_names(role: str, is_performer_role: bool) -> list[str]:
    """Get the tags that a contributor with a role should be put in.

    For example, "drums" gives ["performer:drums (drum set)"], and
    "mastering engineer" gives [], since no tag is used for it.

    :param role: A normalized role, e.g. "drums".
    :param is_performer_role: Whether the role comes after a performer
        category like "Associated Performer". Then the role is an
        instrument or vocals, even if it isn't known, e.g. "theremin"
        gives ["performer:theremin"].

    :return: The tag names, or an empty list if the role has no tag.
    """
    if role in ROLE_TAGS:
        return ROLE_TAGS[role]
    performer_tag = constants.PERFORMER_PREFIX + role
    if performer_tag in constants.performer_tags or is_performer_role:
        return [performer_tag]
    return []


def roles_by_category(roles_text: str) -> list[tuple[str | None, list[str]]]:
    """Group the roles of a credit line under the category before them.

    A category applies to the roles after it, up to the next category.
    For example, "Producer, Studio Personnel, Mixer, Associated
    Performer, Piano" gives:

        [
            (None, ["producer"]),
            ("studio personnel", ["mixer"]),
            ("associated performer", ["piano"]),
        ]

    :param roles_text: The roles of a credit line, separated by commas.

    :return: Each category, or None for the roles before any category,
        with its normalized roles.
    """
    groups: list[tuple[str | None, list[str]]] = [(None, [])]
    for role in roles_text.split(","):
        normalized_role = normalize_role(role)
        if not normalized_role:
            continue
        if normalized_role in PERFORMER_CATEGORIES or normalized_role in OTHER_CATEGORIES:
            groups.append((normalized_role, []))
        else:
            roles_in_last_group = groups[-1][1]
            roles_in_last_group.append(normalized_role)
    return groups


def parse_credit_line(line: str) -> Tags:
    """Turn a credit line into tags.

    For example, "Associated Performer, Drums: Roger Taylor" becomes
    {"performer:drums (drum set)": ["Roger Taylor"]}. Roles that have no
    tag, e.g. "Mastering Engineer", are left out.

    :param line: A line with roles and a name.

    :return: The tags, which are empty if the line has no known roles,
        e.g. "Released on: 2020-01-01".
    """
    roles_text, contributor_name = line.split(": ", 1)
    contributor_name = contributor_name.strip()
    if not contributor_name:
        return {}

    tags: Tags = {}
    for category, roles in roles_by_category(roles_text):
        is_performer_category = category in PERFORMER_CATEGORIES
        # E.g. "Associated Performer: Freddie Mercury", with no instrument
        if is_performer_category and not roles:
            tags["performer"] = [contributor_name]
        for role in roles:
            for tag_name in role_tag_names(role, is_performer_category):
                tags[tag_name] = [contributor_name]
    return tags
